// ORBITAL RESONANCE
// Bodies circle a common centre with periods in simple ratios, and the lines drawn between them weave closed figures: the
// Venus-Earth pentagram is 13:8, a trefoil is 3:2, and a golden-ratio pair never closes at all. The ink lives on its own
// layer that fades at the speed of the memory knob, so the figures can flicker, linger, or pile up for good.
// Variables are re-read every frame.

const CX = 400, CY = 400, R = 360;

// eight frequencies per family; the first n are used for n bodies
const FAMILIES = {
  '13:8 pentagram': [8, 13, 21, 34, 55, 89, 144, 233],
  '3:2 trefoil':    [2, 3, 4, 6, 8, 12, 16, 24],
  '5:3 wheel':      [3, 5, 6, 10, 9, 15, 12, 20],
  '4:1 clover':     [1, 4, 2, 8, 3, 12, 4, 16],
  '7:4 lattice':    [4, 7, 8, 14, 12, 21, 16, 28],
  '8:5 rose':       [5, 8, 10, 16, 15, 24, 20, 32],
  '2:1 oval':       [1, 2, 3, 4, 5, 6, 7, 8],
  '5:2 star':       [2, 5, 4, 10, 6, 15, 8, 20],
  '9:7 meander':    [7, 9, 14, 18, 21, 27, 28, 36],
  'golden drift':   [1, 1.618, 2.618, 4.236, 6.854, 11.09, 17.944, 29.034]
};

const BODIES = { 'a pair': 2, 'a trio': 3, 'a quartet': 4, 'a quintet': 5, 'a sextet': 6, 'a septet': 7, 'an octet': 8 };

// bg: centre and rim; light: pale sky, so ink is drawn dark and there is no glow
const SKY = {
  'midnight blue': { bg: ['#0c1436', '#02030b'], light: false, stars: true },
  'vellum':        { bg: ['#f4ecd6', '#d8cba8'], light: true,  stars: false },
  'slate':         { bg: ['#2c333b', '#0b0d10'], light: false, stars: false },
  'black lacquer': { bg: ['#121214', '#000000'], light: false, stars: true },
  'oxblood':       { bg: ['#451018', '#12040a'], light: false, stars: false },
  'bone':          { bg: ['#ece6d8', '#c0b7a0'], light: true,  stars: false },
  'deep teal':     { bg: ['#0c4248', '#021013'], light: false, stars: true },
  'dawn':          { bg: ['#f2c3a4', '#5b4d86'], light: false, stars: false }
};

const MEMORY = { 'a flicker': 0.22, 'a breath': 0.07, 'a minute': 0.04, 'an hour': 0.022, 'a day': 0.012, 'a season': 0.007, 'a century': 0.003, 'forever': 0.0009 };
const TEMPO = { 'largo': 0.2, 'adagio': 0.4, 'andante': 0.8, 'moderato': 1.1, 'allegro': 1.4, 'vivace': 1.9, 'presto': 2.4, 'prestissimo': 4.0 };

let ink, ictx, bloom, bctx, dust = [];
let th = [0.3, 1.0, 1.7, 2.4, 3.1, 3.8, 4.5, 5.2];
let prev = [];
let clock = 0;

function inkColor(kind, i, t, a, light) {
  if (kind === 'gold leaf') return `rgba(${light ? '150,100,20' : '244,196,98'},${a})`;
  if (kind === 'chalk') return `rgba(${light ? '70,66,60' : '246,246,238'},${a})`;
  if (kind === 'neon') return `hsla(${(t * 40 + i * 47) % 360},100%,${light ? 40 : 62}%,${a})`;
  if (kind === 'etching') return `rgba(${light ? '34,28,22' : '210,200,180'},${a})`;
  if (kind === 'blueprint') return `rgba(${light ? '24,60,140' : '170,208,255'},${a})`;
  if (kind === 'vermilion') return `rgba(${light ? '190,40,20' : '255,92,60'},${a})`;
  if (kind === 'oil slick') return `hsla(${(i * 55 + t * 14 + 180) % 360},85%,${light ? 38 : 60}%,${a})`;
  if (kind === 'starlight') return `rgba(${light ? '40,50,90' : (i % 2 ? '255,246,210' : '210,226,255')},${a})`;
  return `rgba(255,255,255,${a})`;
}

p.setup = function () {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
  p.frameRate(60);
  ink = document.createElement('canvas'); ink.width = 800; ink.height = 800; ictx = ink.getContext('2d');
  bloom = document.createElement('canvas'); bloom.width = 100; bloom.height = 100; bctx = bloom.getContext('2d');
  for (let i = 0; i < 90; i++) dust.push([Math.random() * 800, Math.random() * 800, Math.random() * 1.4 + 0.3, Math.random()]);
};

function positions(n, freq, spiro) {
  const pts = [];
  if (spiro) {
    let x = CX, y = CY, rad = R * 0.36;
    for (let i = 0; i < n; i++) {
      x += Math.cos(th[i]) * rad; y += Math.sin(th[i]) * rad; rad *= 0.62;
      pts.push([x, y]);
    }
  } else {
    for (let i = 0; i < n; i++) {
      const r = R * Math.max(0.14, 0.92 * Math.pow(0.76, n - 1 - i));
      pts.push([CX + Math.cos(th[i]) * r, CY + Math.sin(th[i]) * r, r]);
    }
  }
  return pts;
}

p.draw = function () {
  const family = p.getSynthVar('resonance') || '13:8 pentagram';
  const bodiesKey = p.getSynthVar('bodies') || 'a pair';
  const weave = p.getSynthVar('weave') || 'chords between neighbours';
  const inkKey = p.getSynthVar('ink') || 'gold leaf';
  const skyKey = p.getSynthVar('sky') || 'midnight blue';
  const memKey = p.getSynthVar('memory') || 'a season';
  const tempoKey = p.getSynthVar('tempo') || 'andante';

  const n = BODIES[bodiesKey] || 2;
  const fr = (FAMILIES[family] || FAMILIES['13:8 pentagram']).slice(0, n);
  const sky = SKY[skyKey] || SKY['midnight blue'];
  let fade = MEMORY[memKey] !== undefined ? MEMORY[memKey] : 0.007;
  const speed = TEMPO[tempoKey] || 0.8;
  const spiro = weave === 'a spirograph arm';
  if (weave === 'comet trails') fade = Math.max(fade, 0.045);          // a comet needs a tail, not a ring
  // Line strength follows the fade (a long memory lays thin ink, a short one thick) and the number of lines drawn per
  // frame, so the picture settles at a steady exposure whatever the weave, instead of burning out to a solid disc.
  // load is in 'full chords' per sub-step; pearls and short arcs cover far less of the page than a chord does.
  const load = weave === 'chords between neighbours' ? n - 1
    : weave === 'every chord' ? n * (n - 1) / 2
    : weave === 'a closed polygon' ? n
    : weave === 'triangles' ? 3 * Math.max(1, n - 2)
    : weave === 'a string of pearls' ? 0.1 * (n - 1) : 1;
  const alpha = Math.max(0.006, Math.min(0.42, 500 * fade / (3 * load)));
  const fmax = Math.max.apply(null, fr);

  // fade the ink, then lay down this frame's lines over a few sub-steps so fast bodies still draw unbroken curves
  ictx.globalCompositeOperation = 'destination-out';
  ictx.fillStyle = `rgba(0,0,0,${fade})`; ictx.fillRect(0, 0, 800, 800);
  ictx.globalCompositeOperation = 'source-over';
  ictx.lineWidth = weave === 'comet trails' ? 1.8 : 1.15; ictx.lineCap = 'round';

  const SUB = 3;
  for (let s = 0; s < SUB; s++) {
    for (let i = 0; i < n; i++) {
      const sign = spiro && (i % 2) ? -1 : 1;
      th[i] += sign * 0.2 * (fr[i] / fmax) * speed / SUB * 0.6;
    }
    clock += speed / SUB;
    const cur = positions(n, fr, spiro);
    const t = clock * 0.5;
    if (prev.length === cur.length) {
      if (weave === 'chords between neighbours') {
        for (let i = 0; i < n - 1; i++) { ictx.strokeStyle = inkColor(inkKey, i, t, alpha, sky.light); ictx.beginPath(); ictx.moveTo(cur[i][0], cur[i][1]); ictx.lineTo(cur[i + 1][0], cur[i + 1][1]); ictx.stroke(); }
      } else if (weave === 'every chord') {
        for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) { ictx.strokeStyle = inkColor(inkKey, i + j, t, alpha * 0.8, sky.light); ictx.beginPath(); ictx.moveTo(cur[i][0], cur[i][1]); ictx.lineTo(cur[j][0], cur[j][1]); ictx.stroke(); }
      } else if (weave === 'a closed polygon') {
        ictx.strokeStyle = inkColor(inkKey, 0, t, alpha, sky.light); ictx.beginPath(); ictx.moveTo(cur[0][0], cur[0][1]);
        for (let i = 1; i < n; i++) ictx.lineTo(cur[i][0], cur[i][1]);
        ictx.closePath(); ictx.stroke();
      } else if (weave === 'triangles') {
        for (let i = 0; i < Math.max(1, n - 2); i++) {
          const a = cur[i], b = cur[Math.min(n - 1, i + 1)], c = cur[Math.min(n - 1, i + 2)];
          ictx.strokeStyle = inkColor(inkKey, i, t, alpha, sky.light); ictx.beginPath(); ictx.moveTo(a[0], a[1]); ictx.lineTo(b[0], b[1]); ictx.lineTo(c[0], c[1]); ictx.closePath(); ictx.stroke();
        }
      } else if (weave === 'a string of pearls') {
        for (let i = 0; i < n - 1; i++) {
          ictx.fillStyle = inkColor(inkKey, i, t, Math.min(0.9, alpha * 2.4), sky.light); ictx.beginPath();
          for (let k = 1; k <= 7; k++) {
            const f = k / 8, x = cur[i][0] + (cur[i + 1][0] - cur[i][0]) * f, y = cur[i][1] + (cur[i + 1][1] - cur[i][1]) * f;
            ictx.moveTo(x + 1.2, y); ictx.arc(x, y, 1.2, 0, 6.2832);
          }
          ictx.fill();
        }
      } else if (weave === 'a spirograph arm') {
        ictx.strokeStyle = inkColor(inkKey, n, t, 0.85, sky.light); ictx.lineWidth = 1.5; ictx.beginPath();
        ictx.moveTo(prev[n - 1][0], prev[n - 1][1]); ictx.lineTo(cur[n - 1][0], cur[n - 1][1]); ictx.stroke();
      } else {                                      // 'comet trails'
        for (let i = 0; i < n; i++) { ictx.strokeStyle = inkColor(inkKey, i, t, 0.9, sky.light); ictx.beginPath(); ictx.moveTo(prev[i][0], prev[i][1]); ictx.lineTo(cur[i][0], cur[i][1]); ictx.stroke(); }
      }
    }
    prev = cur;
  }

  // sky
  const ctx = p.drawingContext;
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  const g = ctx.createRadialGradient(CX, CY, 30, CX, CY, 600);
  g.addColorStop(0, sky.bg[0]); g.addColorStop(1, sky.bg[1]);
  ctx.fillStyle = g; ctx.fillRect(0, 0, 800, 800);
  if (sky.stars) {
    for (let i = 0; i < dust.length; i++) {
      const d = dust[i], tw = 0.4 + 0.6 * Math.abs(Math.sin(p.frameCount * 0.02 + d[3] * 30));
      ctx.fillStyle = `rgba(255,255,255,${0.35 * tw})`; ctx.fillRect(d[0], d[1], d[2], d[2]);
    }
  }

  // the structure the ink is woven from: rings and arms, drawn faintly
  const cur = prev;
  ctx.lineWidth = 1;
  if (!spiro) {
    ctx.strokeStyle = sky.light ? 'rgba(40,30,20,0.12)' : 'rgba(255,255,255,0.09)';
    for (let i = 0; i < cur.length; i++) { ctx.beginPath(); ctx.arc(CX, CY, cur[i][2], 0, 6.2832); ctx.stroke(); }
  } else {
    ctx.strokeStyle = sky.light ? 'rgba(40,30,20,0.35)' : 'rgba(255,255,255,0.3)';
    ctx.beginPath(); ctx.moveTo(CX, CY);
    for (let i = 0; i < cur.length; i++) ctx.lineTo(cur[i][0], cur[i][1]);
    ctx.stroke();
  }

  // ink over the sky, with a cheap bloom on dark skies
  ctx.drawImage(ink, 0, 0);
  if (!sky.light) {
    bctx.clearRect(0, 0, 100, 100); bctx.imageSmoothingEnabled = true; bctx.imageSmoothingQuality = 'high';
    bctx.drawImage(ink, 0, 0, 100, 100);
    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.9;
    ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(bloom, 0, 0, 800, 800);
    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  }

  // the bodies themselves
  for (let i = 0; i < cur.length; i++) {
    ctx.fillStyle = sky.light ? 'rgba(30,24,18,0.9)' : 'rgba(255,248,230,0.95)';
    ctx.beginPath(); ctx.arc(cur[i][0], cur[i][1], i === cur.length - 1 ? 4.5 : 3.2, 0, 6.2832); ctx.fill();
  }
};
